SELECT id, customer_id, store_id, status, channel, amount, discount, shipping_fee, SUM(shipping_fee) OVER w_hist running_sum_shipping_fee, MIN(shipping_fee) OVER w_hist running_min_shipping_fee, COUNT(shipping_fee) OVER w_hist running_count_shipping_fee FROM orders WINDOW w_hist AS (PARTITION BY store_id, customer_id ORDER BY discount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
